import { sql } from 'drizzle-orm';
import { sqliteTable, integer, text, real, customType, primaryKey, index, uniqueIndex, foreignKey, check, type AnySQLiteColumn } from 'drizzle-orm/sqlite-core';

const nocaseText = customType<{ data: string; driverData: string }>({ dataType: () => 'text COLLATE NOCASE' });
const binaryData = customType<{ data: Uint8Array; driverData: ArrayBuffer | Uint8Array }>({ dataType: () => 'blob', toDriver: (value) => value, fromDriver: (value) => value instanceof Uint8Array ? value : new Uint8Array(value) });

export const abtest = sqliteTable("abtest", {
  id: integer("id").primaryKey({ autoIncrement: true }).notNull(),
  title: nocaseText("title").notNull(),
  display_title: nocaseText("display_title").notNull(),
  description: nocaseText("description"),
  creator: nocaseText("creator"),
  team: nocaseText("team"),
  winner_id: integer("winner_id"),
  status: nocaseText("status").notNull().default(sql.raw("'IN_PROGRESS'")),
  created_at: text("created_at").notNull().default(sql.raw("CURRENT_TIMESTAMP")),
  updated_at: text("updated_at").notNull().default(sql.raw("CURRENT_TIMESTAMP")),
}, (table) => [
  check("abtest_id_type_0", sql.raw("\"id\" IS NULL OR typeof(\"id\") = 'integer'")),
  check("abtest_id_type_1", sql.raw("\"id\" >= 0 AND \"id\" <= 4294967295")),
  check("abtest_title_type_0", sql.raw("length(\"title\") <= 255")),
  check("abtest_display_title_type_0", sql.raw("length(\"display_title\") <= 255")),
  check("abtest_description_type_0", sql.raw("length(\"description\") <= 255")),
  check("abtest_creator_type_0", sql.raw("length(\"creator\") <= 50")),
  check("abtest_team_type_0", sql.raw("length(\"team\") <= 50")),
  check("abtest_winner_id_type_0", sql.raw("\"winner_id\" IS NULL OR typeof(\"winner_id\") = 'integer'")),
  check("abtest_winner_id_type_1", sql.raw("\"winner_id\" >= 0 AND \"winner_id\" <= 4294967295")),
  check("abtest_status_type_0", sql.raw("length(\"status\") <= 50")),
  foreignKey({ name: "FK_ABTEST_ON_WINNER_ID", columns: [table.winner_id], foreignColumns: ((): [AnySQLiteColumn] => [abtest_variable.id])() }).onDelete("no action").onUpdate("no action"),
  index("abtest__FK_ABTEST_ON_WINNER_ID_idx").on(table.winner_id),
  uniqueIndex("abtest__title_UNIQUE").on(table.title),
]);

export const abtest_variable = sqliteTable("abtest_variable", {
  id: integer("id").primaryKey({ autoIncrement: true }).notNull(),
  abtest_id: integer("abtest_id").notNull(),
  name: nocaseText("name").notNull(),
  display_name: nocaseText("display_name").notNull(),
  rate: integer("rate").notNull(),
  count: integer("count").notNull().default(sql.raw("'0'")),
  created_at: text("created_at").notNull().default(sql.raw("CURRENT_TIMESTAMP")),
  updated_at: text("updated_at").notNull().default(sql.raw("CURRENT_TIMESTAMP")),
}, (table) => [
  check("abtest_variable_id_type_0", sql.raw("\"id\" IS NULL OR typeof(\"id\") = 'integer'")),
  check("abtest_variable_id_type_1", sql.raw("\"id\" >= 0 AND \"id\" <= 4294967295")),
  check("abtest_variable_abtest_id_type_0", sql.raw("\"abtest_id\" IS NULL OR typeof(\"abtest_id\") = 'integer'")),
  check("abtest_variable_abtest_id_type_1", sql.raw("\"abtest_id\" >= 0 AND \"abtest_id\" <= 4294967295")),
  check("abtest_variable_name_type_0", sql.raw("length(\"name\") <= 255")),
  check("abtest_variable_display_name_type_0", sql.raw("length(\"display_name\") <= 255")),
  check("abtest_variable_rate_type_0", sql.raw("\"rate\" IS NULL OR typeof(\"rate\") = 'integer'")),
  check("abtest_variable_rate_type_1", sql.raw("\"rate\" >= 0 AND \"rate\" <= 4294967295")),
  check("abtest_variable_count_type_0", sql.raw("\"count\" IS NULL OR typeof(\"count\") = 'integer'")),
  check("abtest_variable_count_type_1", sql.raw("\"count\" BETWEEN -2147483648 AND 2147483647")),
  foreignKey({ name: "FK_ABTEST_VARIABLE_ON_ABTEST_ID", columns: [table.abtest_id], foreignColumns: ((): [AnySQLiteColumn] => [abtest.id])() }).onDelete("no action").onUpdate("no action"),
  index("abtest_variable__FK_ABTEST_VARIABLE_ON_ABTEST_ID_idx").on(table.abtest_id),
]);

export const academic_program_year = sqliteTable("academic_program_year", {
  id: integer("id").primaryKey({ autoIncrement: true }).notNull(),
  student_year: nocaseText("student_year").notNull(),
  department_id: integer("department_id").notNull(),
  major_id: integer("major_id"),
  major_key: integer("major_key").generatedAlwaysAs(sql.raw("ifnull(`major_id`,0)"), { mode: 'stored' }),
}, (table) => [
  check("academic_program_year_id_type_0", sql.raw("\"id\" IS NULL OR typeof(\"id\") = 'integer'")),
  check("academic_program_year_id_type_1", sql.raw("\"id\" >= 0 AND \"id\" <= 4294967295")),
  check("academic_program_year_student_year_type_0", sql.raw("length(\"student_year\") <= 4")),
  check("academic_program_year_department_id_type_0", sql.raw("\"department_id\" IS NULL OR typeof(\"department_id\") = 'integer'")),
  check("academic_program_year_department_id_type_1", sql.raw("\"department_id\" >= 0 AND \"department_id\" <= 4294967295")),
  check("academic_program_year_major_id_type_0", sql.raw("\"major_id\" IS NULL OR typeof(\"major_id\") = 'integer'")),
  check("academic_program_year_major_id_type_1", sql.raw("\"major_id\" >= 0 AND \"major_id\" <= 4294967295")),
  check("academic_program_year_major_key_type_0", sql.raw("\"major_key\" IS NULL OR typeof(\"major_key\") = 'integer'")),
  check("academic_program_year_major_key_type_1", sql.raw("\"major_key\" >= 0 AND \"major_key\" <= 4294967295")),
  foreignKey({ name: "fk_academic_program_year_department", columns: [table.department_id], foreignColumns: ((): [AnySQLiteColumn] => [department.id])() }).onDelete("no action").onUpdate("no action"),
  foreignKey({ name: "fk_academic_program_year_major", columns: [table.major_id], foreignColumns: ((): [AnySQLiteColumn] => [major.id])() }).onDelete("no action").onUpdate("no action"),
  index("academic_program_year__fk_academic_program_year_department").on(table.department_id),
  index("academic_program_year__idx_academic_program_year_major").on(table.major_id),
  uniqueIndex("academic_program_year__ux_academic_program_year").on(table.student_year, table.department_id, table.major_key),
]);

